/**
 * Shared split-loading helper for benchmark runners.
 *
 * Implements the dev/held-out methodology mandated in CLAUDE.md / AGENTS.md:
 * external split files (eval/splits/<bench>/<dev|heldout>.json) generated by
 * eval/scripts/generate-splits.js are the source of truth.
 *
 * Default behaviour preserves backwards compatibility — `--split=all` (or no
 * flag) runs the full bench. `dev` and `heldout` filter to the persisted
 * subset. Anything else throws.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, '..', '..');

export const VALID_SPLITS = new Set(['dev', 'heldout', 'all']);

/**
 * Resolve and validate a `--split` argument.
 * @param {string|undefined|null} raw - value from CLI
 * @returns {'dev'|'heldout'|'all'}
 */
export function normalizeSplit(raw) {
  if (raw == null || raw === '') return 'all';
  const v = String(raw).toLowerCase();
  if (v === 'held-out' || v === 'held_out' || v === 'holdout') return 'heldout';
  if (!VALID_SPLITS.has(v)) {
    throw new Error(`Invalid --split=${raw}. Expected one of: dev, heldout, all`);
  }
  return v;
}

/**
 * Load a persisted split as a Set of IDs. Throws if the split file is missing.
 *
 * @param {string} bench - e.g. 'gencodesearchnet', 'multirepo', 'retrieval-probes'
 * @param {'dev'|'heldout'} which
 * @returns {Set<string>}
 */
export function loadSplitIds(bench, which) {
  if (which !== 'dev' && which !== 'heldout') {
    throw new Error(`loadSplitIds: which must be 'dev' or 'heldout', got ${which}`);
  }
  const filePath = path.join(REPO_ROOT, 'eval', 'splits', bench, `${which}.json`);
  if (!fs.existsSync(filePath)) {
    throw new Error(
      `Missing split file: ${filePath}\n` +
      `Run \`node eval/scripts/generate-splits.js --bench=${bench}\` first.`,
    );
  }
  const parsed = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
  const ids = parsed.ids || [];
  return new Set(ids);
}

/**
 * Filter an array of items by split membership.
 *
 * @param {Array<T>} items
 * @param {'dev'|'heldout'|'all'} split
 * @param {string} bench - bench name (matches eval/splits/<bench>/)
 * @param {(item: T) => string} idAccessor - extracts the id used in the split file
 * @returns {{ items: Array<T>, dropped: number }}
 */
export function applySplit(items, split, bench, idAccessor) {
  if (split === 'all') return { items, dropped: 0 };
  const allowed = loadSplitIds(bench, split);
  const filtered = items.filter(it => allowed.has(idAccessor(it)));
  return { items: filtered, dropped: items.length - filtered.length };
}

/**
 * Print a one-line warning when running on the full bench.
 * Methodology in CLAUDE.md/AGENTS.md says full-bench runs are for milestone
 * reports only — iteration should use --split=dev. Non-blocking; just a
 * reminder.
 */
export function warnIfFullSplit(split, benchLabel) {
  if (split === 'all') {
    console.log(
      `  [methodology] Running ${benchLabel} on full set (--split=all). ` +
      `For iteration use --split=dev; reserve --split=heldout / --split=all for milestones.`,
    );
  }
}
